NAME = 'SweKarlXII: Svenska Karl XII:s Bibel (1703)'
BOOK = 'I Thessalonians'

CHAPTERS = {
    1: {
        1: 'Paulus, och Silvanus, och Timotheus: Den församling i Thessalonica, uti Gud Fader, och HERranom JEsu Christo: Nåd ware med eder, och frid af Gudi, wårom Fader, och HERranom JEsu Christo.',
        2: 'Wi tackom Gudi alltid för eder alla, och hafwom eder i åminnelse i wåra böner, utan återwändo:',
        3: 'Tänkande på edart werk i trone, och på edart arbete i kärleken, och på edart tålamod i hoppet, hwilket är wår HERre, JEsus Christus, för Gudi och wårom Fader.',
        4: 'Ty, käre bröder, af Gudi älskade, wi wete, huru I ären utwalde;',
        5: 'At wårt Ewangelium hafwer warit när eder, icke allenast med ordom, utan både i kraft, och i den Helga Anda, och i fulla wisshet, såsom I weten, hurudane wi worom när eder, för edra skull.',
        6: 'Och I ären wordne wåre efterföljare, och HERrans; och hafwen anammat ordet ibland mång bedröfwelse, med den Helga Andas fröjd:',
        7: 'Så at I ären wordne en efterdömelse allom trognom uti Macedonia och Achaja.',
        8: 'Ty af eder är HERrans ord utgånget, icke allenast i Macedonia, och Achaja; utan ock i all rum är edor tro, som I hafwen til Gud, utkommen; så at oss är icke behof at säga något.',
        9: 'Ty de sjelfwe förkunna om eder, hurudana ingång wi hadom til eder; och huru I omwände worden til Gud ifrån afgudarna, til at tjena den lefwande och sanna Gud;',
        10: 'Och til at wänta hans Son af himmelen, hwilken han upwäckt hafwer ifrå de döda, JEsum, den oss frälsar ifrå den tilkommande wrede.',
    },
    2: {
        1: 'Käre bröder, I weten sjelfwe wår ingång til eder, at han war icke fåfäng:',
        2: 'Utan, såsom wi tilförene hade lidit, och försmådde warit uti Philippis, som I veten, worom wi ändå wid god tröst i wårom Gud, til at tala när eder Guds Ewangelium, med mycken kämpning.',
        3: 'Ty wår förmaning war icke til willfarelse, icke heller til orenlighet, icke heller med list:',
        4: 'Utan, såsom wi af Gudi bepröfwade worom, at oss Ewangelium betrodt är til at predika, så talom wi: icke såsom wi wille täckas menniskom, utan Gudi, den der pröfwar wår hjerta.',
        5: 'Ty wi hafwe icke umgått med smekligom ordom, såsom I weten, icke heller med tilfälle til girighet; Gud är dess wittne.',
        6: 'Hafwom icke heller sökt pris af menniskom, hwarken af eder, eller androm.',
        7: 'Ändock wi wäl hadom haft magt at förtunga eder, såsom Christi Apostlar; men wi worom milde när eder, lika som en amma fostrar sin barn.',
        8: 'Så hafwom wi hjertans lust haft til eder, at dela med eder, icke allenast Guds Ewangelium, utan ock wårt eget lif; ty I ären oss käre wordne.',
        9: 'I minnens wäl, käre bröder, wårt arbete och wår mödo; ty dag och natt arbetade wi, på det wi ingen af eder skulle förtunga; och predikadom ibland eder Guds Ewangelium.',
        10: 'Dess ären I wittne, och Gud, huru heliga, huru rättfärdeliga och ostraffeliga wi umgingom med eder, som trodden.',
        11: 'Såsom I weten, at wi, såsom en fader sin barn, hafwe förmanat och tröstat hwar och en ibland eder;',
        12: 'Och betygat, at I wärdeliga skullen wandra för Gudi, den eder kallat hafwer til sitt rike och härlighet.',
        13: 'För hwilket wi ock utan återwändo tackom Gudi, at då I anammaden af oss det predikade ordet om Gud, anammaden I det icke såsom menniskors ord, utan såsom det sannerliga är, som Guds ord, hwilken ock werkar i eder, som tron.',
        14: 'Ty I ären wordne, käre bröder, de Guds församlingars efterföljare, som uti Judeen äro, i Christo JEsu, at I detsamma lidit hafwen af edra egna fränder, som de af Judomen.',
        15: 'Hwilke ock HERran JEsum dråpo, och sina egna Propheter, och hafwa förföljt oss, och täckas icke Gudi, och allom menniskom äro de emot:',
        16: 'Förbjuda oss underwisa Hedningomen, dermed de skola salige warda, på det de skola fullkomna sina synder alltid; ty wreden är kommen öfwer dem intil ändan.',
        17: 'Men wi, käre bröder, sedan wi til någon tid hade mist eder efter ansigtet, och icke efter hjertat, hafwe wi dess mer hastat til at se edart ansigte, med stor begärelse.',
        18: 'Derföre hadom wi welat komma til eder, (jag Paulus) twå resor; och Satanas hafwer oss förhindrat.',
        19: 'Ty hwad är wårt hopp, eller fröjd, eller kronan til wår berömelse? Ären ock icke I det, för warom HERra JEsu Christo i hans tilkommelse?',
        20: 'I ären ju wår pris och fröjd.',
    },
    3: {
        1: 'Derföre kundom wi icke längre hafwat fördrag; och oss syntes, at wi uti Athen allena skulle qware blifwa.',
        2: 'Och hafwe sändt Timotheum, wår broder, och Guds tjenare, och wår hjelpare i Ewangelio Christi, til at styrka och trösta eder i edra tro:',
        3: 'På det ingen skulle låta wika sig uti denna bedröfwelse; ty I weten, at wi ärom dertil satte.',
        4: 'Ty när wi worom när eder, sade wi eder det tilförene, at wi måste lida bedröfwelse; såsom ock skedt är, och I weten.',
        5: 'Derföre kunde jag ock icke länger hafwat fördrag, utan sände åstad; på det jag skulle förfara edra tro, at til äfwentyrs frestaren icke hade försökt eder, och wårt arbete hade då fåfängt wordit.',
        6: 'Men nu nyliga, sedan Timotheus kommen war til oss ifrån eder, och underwiste oss edra tro och kärlek; och at I alltid tänken på oss til det bästa, och åstunden at se oss, såsom ock wi eder:',
        7: 'Wordom wi, käre bröder, hugswalade på eder, uti all wår bedröfwelse och nöd, genom edra tro.',
        8: 'Ty wi lefwe nu, efter I stån i HERranom.',
        9: 'Hwad tack kunne wi Gudi säga för eder. för all den glädje, som wi hafwe af eder, för wår Gud?',
        10: 'wi bedje dag och natt ganska mycket, at wi mågom se edart ansigte, och upfylla det i edra tro fattas.',
        11: 'Men Gud sjelfwer, och wår Fader, och wår HERre JEsus Christus, skicke wår wäg til eder.',
        12: 'Men HERren föröke eder, och låte kärleken öfwerflöda inbördes och til hwar man; såsom ock wi äre til eder:',
        13: 'At edor hjerta måga styrkt och ostraffelig blifwa, i helighet, för Gudi och wårom Fader, uti wårs HERras JEsu Christi tilkommelse, med all hans helgon.',
    },
    4: {
        1: 'Yttermera, käre bröder, bedje wi eder, och förmane genom wår HERra JEsum, såsom I hafwen undfångit af oss, huru I wandra skolen, och täckas Gudi, at I ju mer fullkomlige warden.',
        2: 'Ty I weten hwad bud wi gåfwom eder, genom HERran JEsum.',
        3: 'Ty deta är Guds wilje, edor helgelse, at I flyn boleri:',
        4: 'Och hwar och en af eder wet behålla sitt fat i helgelse och äro:',
        5: 'Icke uti lustig begärelse, såsom Hedningar, de som af Gudi intet weta.',
        6: 'Och at ingen förtrycker eller swiker sin broder i någon handel; ty HERren är hämnaren öfwer allt deta; såsom wi ock eder tilförene sadom och betygadom.',
        7: 'Ty Gud hafwer icke kallat oss till orenlighet, utan til helgelse.',
        8: 'Den der nu föraktar, han föraktar icke någon mennisko, utan Gud, den sin Helga Anda hafwer gifwit i eder.',
        9: 'Men om broderlig kärlek görs icke behof, at jag skrifwer eder; ty I ären sjelfwe lärde af Gudi, at I skolen älska eder inbördes.',
        10: 'Och det gören I ock på alla bröderna, som i hela Macedonien äro; men wi förmane eder, käre bröder, at I ju mer fullkomlige warden.',
        11: 'Och winlägger eder, at I ären rolige, och sköter edor egen stycke; och arbeter med edra händer, såsom wi eder budit hafwe:',
        12: 'At I hafwen eder ärliga med dem, som utantil äro, och at I deras intet betorfwen.',
        13: 'Men wi wilje icke dölja för eder, käre bröder, om dem som afsomnade äro, at I icke sörjen, såsom de andre, de der intet hopp hafwa.',
        14: 'Ty om wi tro, at JEsus är döder och upstånden; så skall ock Gud dem som afsomnade äro, genom JEsum framhafwa med honom.',
        15: 'Ty detta säge wi eder, såsom HERrans ord; at wi som lefwe och igenblifwe uti HERrans tillkommelse, skole icke förekomma dem som sofwa.',
        16: 'Ty sjelfwer HERren skall stiga ned af himmelen med härskri, och öfwerängels röst, och med Guds basun, och de döde i Christo skola upstå i förstone:',
        17: 'Derefter wi som lefwe och igenblifwe, wardom tillika med dem borttagne i skyn emot HERran i wädret, och så skole wi blifwa när HERranom alltid.',
        18: 'Så tröster eder nu med dessa orden inbördes.',
    },
    5: {
        1: 'Men om tider och stunder, käre bröder, är icke behof at skrifwa eder.',
        2: 'Ty I weten wäl, at HERrans dag skall komma såsom en tjuf om nattene.',
        3: 'Derföre, när de warda sägande: Det är frid, och all ting utan fara, då skall dem hasteligit förderf öfwerkomma; lika som födslopinan qwinnone påkommer, som hafwandes är, och de skola icke kunna undfly.',
        4: 'Men I, käre bröder, ären icke uti mörkret, at den dagen, såsom en tjuf, skall få eder fatt.',
        5: 'Alle I ären ljusens barn, och dagsens barn; wi hörom icke nattene til, icke heller mörkret.',
        6: 'Så låter oss nu icke sofwa, såsom de andre; utan låter oss waka och nyktre wara;',
        7: 'Ty de som sofwa, de sofwa om nattene, och de som druckne äro, de äro druckne om nattene.',
        8: 'Men wi, som dagen tilhöre, skole nyktre wara, iklädde trones och kärlekens kräfweto, och salighetenes hopp för en hjelm.',
        9: 'Ty Gud hafwer icke satt oss til wrede, utan at äga salighet, genom wår HERra JEsum Christum;',
        10: 'Den för oss död är; på det, ehwad wi wake eller sofwe, skole wi lefwa samt med honom.',
        11: 'Derföre förmaner eder inbördes; och upbygger hwar den andra, såsom I ock gören.',
        12: 'Men wi bedje eder, käre bröder, at I kännen dem som arbeta ibland eder, och stå eder före i HERranom, och förmana eder:',
        13: 'Håller dem dess kärare, för deras werks skull, och warer fridsamme med dem.',
        14: 'Men wi bedje eder, käre bröder, förmaner de osediga, tröster de klenmodiga, hjelper de swaga, warer långmodige wid hwar man.',
        15: 'Ser til, at ingen wedergäller någrom ondt för ondt; utan alltid farer efter det goda inbördes, och med hwar man.',
        16: 'warer alltid glade.',
        17: 'Bedjen utan återwändo.',
        18: 'warer tacksamme i all ting; ty det är Guds wilje om eder, genom JEsum Christum.',
        19: 'Utsläcker icke Andan.',
        20: 'Förakter icke Prophetier.',
        21: 'Men pröfwer all ting, och behåller det godt är.',
        22: 'Flyr allt det som ondt synes.',
        23: 'Men sjelfwer fridsens Gud helge eder öfwer allt, at edar hele ande, och själ, och kropp, måtte wara behållen utan straff, i wårs HERras JEsu Christi tilkommelse.',
        24: 'Han är trofast, som eder kallat hafwer; den det ock wäl fullbordar.',
        25: 'Käre bröder, beder för oss.',
        26: 'Helser alla bröderna uti en helig kyss.',
        27: 'Jag beswär eder wid HERran, at I denna Epistelen läsa låten för alla heliga bröderna.',
        28: 'Wårs HERras JEsu Christi nåd ware med eder. Amen. Til de Thessalonicer den förra, skrifwen af Athen.',
    },
}
